static int read_int(const char **p) {
    while (**p == ' ' || **p == ',' || **p == '[' || **p == ']') (*p)++;
    int sign = 1;
    if (**p == '-') { sign = -1; (*p)++; }
    int x = 0;
    while (**p >= '0' && **p <= '9') { x = x * 10 + (**p - '0'); (*p)++; }
    return sign * x;
}

int largestIsland(int **grid, int n, int *cols) {
    int *area = (int *)calloc(n * n + 2, sizeof(int));
    int *stack = (int *)malloc((size_t)n * n * sizeof(int));
    int id = 2, best = 0;

    for (int r = 0; r < n; ++r) {
        for (int c = 0; c < n; ++c) {
            if (grid[r][c] != 1) continue;
            int top = 0;
            stack[top++] = r * n + c;
            grid[r][c] = id;
            int size = 0;
            while (top > 0) {
                int pos = stack[--top];
                int cr = pos / n, cc = pos % n;
                ++size;
                if (cr > 0 && grid[cr - 1][cc] == 1) {
                    grid[cr - 1][cc] = id;
                    stack[top++] = (cr - 1) * n + cc;
                }
                if (cr + 1 < n && grid[cr + 1][cc] == 1) {
                    grid[cr + 1][cc] = id;
                    stack[top++] = (cr + 1) * n + cc;
                }
                if (cc > 0 && grid[cr][cc - 1] == 1) {
                    grid[cr][cc - 1] = id;
                    stack[top++] = cr * n + cc - 1;
                }
                if (cc + 1 < n && grid[cr][cc + 1] == 1) {
                    grid[cr][cc + 1] = id;
                    stack[top++] = cr * n + cc + 1;
                }
            }
            area[id] = size;
            if (size > best) best = size;
            ++id;
        }
    }

    if (best == n * n) {
        free(area); free(stack); return best;
    }

    for (int r = 0; r < n; ++r) {
        for (int c = 0; c < n; ++c) {
            if (grid[r][c] != 0) continue;
            int ids[4], count = 0, total = 1;
            int dr[4] = {-1, 1, 0, 0};
            int dc[4] = {0, 0, -1, 1};
            for (int d = 0; d < 4; ++d) {
                int nr = r + dr[d], nc = c + dc[d];
                if (nr < 0 || nr >= n || nc < 0 || nc >= n) continue;
                int nid = grid[nr][nc];
                if (nid <= 1) continue;
                int seen = 0;
                for (int i = 0; i < count; ++i) if (ids[i] == nid) seen = 1;
                if (!seen) { ids[count++] = nid; total += area[nid]; }
            }
            if (total > best) best = total;
        }
    }
    free(area); free(stack);
    return best == 0 ? 1 : best;
}

