public class Main {
    static String readLine() throws Exception {
        return new BufferedReader(new InputStreamReader(System.in)).readLine().trim();
    }

    static String[] splitTop(String s) {
        List<String> parts = new ArrayList<>();
        int depth = 0, start = 0;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch == '[') depth++;
            else if (ch == ']') depth--;
            else if (ch == ',' && depth == 0) {
                parts.add(s.substring(start, i).trim());
                start = i + 1;
            }
        }
        parts.add(s.substring(start).trim());
        return parts.toArray(new String[0]);
    }

    static int[] parseRow(String s) {
        s = s.trim();
        if (s.equals("[]")) return new int[0];
        String inner = s.substring(1, s.length() - 1);
        String[] parts = splitTop(inner);
        int[] row = new int[parts.length];
        for (int i = 0; i < parts.length; i++) row[i] = Integer.parseInt(parts[i]);
        return row;
    }

    static int[][] parseGrid(String s) {
        s = s.trim();
        String outer = s.substring(1, s.length() - 1);
        String[] rows = splitTop(outer);
        int[][] grid = new int[rows.length][];
        for (int i = 0; i < rows.length; i++) grid[i] = parseRow(rows[i]);
        return grid;
    }

    public static void main(String[] args) throws Exception {
        String line = readLine();
        String outer = line.substring(1, line.length() - 1);
        int[][] grid = parseGrid(outer);
        System.out.println(new Solution().largestIsland(grid));
    }
}

